function initTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(o=>{o.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>e.classList.remove("active")),o.classList.add("active"),o.setAttribute("aria-selected","true"),document.getElementById(o.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const e=document.getElementById("dabhol-quiz-form"),t=document.getElementById("quiz-result"),o={q1:"2",q2:"2"};e&&e.addEventListener("submit",n=>{n.preventDefault();let i=0;const r=new FormData(e);for(let[e,t]of r.entries())o[e]===t&&i++;const l=Object.keys(o).length;t.textContent=i===l?`🎉 Perfect! ${i}/${l}`:`You scored ${i}/${l}`,t.style.color=i===l?"green":"orange"})}function initGalleryModal(){const e=document.getElementById("gallery-modal"),t=document.getElementById("modal-title"),o=document.getElementById("modal-desc"),n=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(n=>{n.addEventListener("click",()=>{t.textContent=n.getAttribute("data-title"),o.textContent=n.getAttribute("data-desc"),e.classList.add("active")})}),n&&n.addEventListener("click",()=>e.classList.remove("active")),window.addEventListener("click",t=>{t.target===e&&e.classList.remove("active")})}function initScrollTop(){const e=document.getElementById("btn-scroll-top");e&&(window.addEventListener("scroll",()=>e.classList.toggle("visible",window.scrollY>300)),e.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("dabhol-port-explorer/index.html",[{id:"dabhol-overview",title:"Dabhol Historical Overview",description:"Gateway to the Deccan Sultanates.",link:"dabhol-port-explorer/index.html#overview"},{id:"dabhol-economy",title:"Horse Trade",description:"Import of Arabian warhorses.",link:"dabhol-port-explorer/index.html#economy"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});